/**
 * @summary Update tenant plan/status (super-admin)
 */
export const getAdminUpdateTenantUrl = (tenantId: string) => {
  return `/api/admin/tenants/${tenantId}`;
};

export const adminUpdateTenant = async (
  tenantId: string,
  adminUpdateTenantBody: AdminUpdateTenantBody,
  options?: RequestInit,
): Promise<Tenant> => {
  return customFetch<Tenant>(getAdminUpdateTenantUrl(tenantId), {
    ...options,
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(adminUpdateTenantBody),
  });
};

export const getAdminUpdateTenantMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof adminUpdateTenant>>,
    TError,
    { tenantId: string; data: BodyType<AdminUpdateTenantBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof adminUpdateTenant>>,
  TError,
  { tenantId: string; data: BodyType<AdminUpdateTenantBody> },
  TContext
> => {
  const mutationKey = ["adminUpdateTenant"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof adminUpdateTenant>>,
    { tenantId: string; data: BodyType<AdminUpdateTenantBody> }
  > = (props) => {
    const { tenantId, data } = props ?? {};

    return adminUpdateTenant(tenantId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type AdminUpdateTenantMutationResult = NonNullable<
  Awaited<ReturnType<typeof adminUpdateTenant>>
>;
export type AdminUpdateTenantMutationBody = BodyType<AdminUpdateTenantBody>;
export type AdminUpdateTenantMutationError = ErrorType<unknown>;

/**
 * @summary Update tenant plan/status (super-admin)
 */
export const useAdminUpdateTenant = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof adminUpdateTenant>>,
    TError,
    { tenantId: string; data: BodyType<AdminUpdateTenantBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof adminUpdateTenant>>,
  TError,
  { tenantId: string; data: BodyType<AdminUpdateTenantBody> },
  TContext
> => {
  return useMutation(getAdminUpdateTenantMutationOptions(options));
};

